test('Memory Profiler', async ({ page }) => {
  await page.goto('/');
  const startMetrics = await page.evaluate(() => performance.memory.usedJSHeapSize);
  for(let i=0; i<100; i++) { await page.click('#refresh'); }
  const endMetrics = await page.evaluate(() => performance.memory.usedJSHeapSize);
  expect(endMetrics - startMetrics).toBeLessThan(50000000); // 50MB limit
});

